      if (!token) {
        CDT.assert(r.Data.TotalCount === undefined || seen === CDT.amount(r.Data.TotalCount), '账单记录数量不完整');
        return { amount: Math.round(total * 100) / 100, currency: currency };
      }
      CDT.assert(items.length > 0 && !tokens[token], '账单分页无进展');
