      var r = state.accounts[a.id];
      return a.name + ': ' + (typeof r.trafficGiB === 'number' ? r.trafficGiB.toFixed(2) + ' GiB' : '暂无数据') + ' / ' + r.status + (r.trafficFresh ? '' : '（缓存或查询失败）');
